#pragma once

#include <algorithm>
#include <array>

// Generated by 4414/1690 Shot Polynomial Generator (Stage 1)
// Basis: [1, d, v, d^2, d*v, v^2, d^3, d^2*v, d*v^2, v^3]
// d = distance to target (m), v = radial velocity toward target (m/s)
constexpr std::array<double, 10> kExitVelCoeffs = { 6.937302, -0.383669, 0.629612, 0.184579, -0.437636, 0.187598, -0.009616, 0.035366, -0.028169, 0.006635 };
constexpr std::array<double, 10> kHoodAngCoeffs = { 11.655359, 28.346257, -24.512394, -5.623951, 9.869327, -3.353412, 0.334469, -0.867655, 0.407719, -0.013654 };
constexpr std::array<double, 10> kTofCoeffs     = { -0.753937, 0.918343, -0.643033, -0.157121, 0.208000, -0.049273, 0.009685, -0.017969, 0.003673, 0.002548 };

// Hard Hardware Limits (prevent impossible setpoints on the real robot)
constexpr double kMinExitVelMps = 7.00;
constexpr double kMaxExitVelMps = 22.00;
constexpr double kMinHoodDeg    = 15.00;
constexpr double kMaxHoodDeg    = 60.00;
constexpr double kMinDistM      = 1.20;
constexpr double kMaxDistM      = 7.00;
constexpr double kMaxTurretDeg  = 180.0; // Tune to SubTurret soft limits

inline double EvalPoly3(const std::array<double, 10>& c, double d, double v) {
  return c[0] + c[1]*d + c[2]*v + c[3]*d*d + c[4]*d*v + c[5]*v*v
       + c[6]*d*d*d + c[7]*d*d*v + c[8]*d*v*v + c[9]*v*v*v;
}

struct ClampedShot {
  double exitVelMps;
  double hoodAngleDeg;
  double tofSec;
  bool isValid;
};

inline ClampedShot EvaluateClampedShot(double distM, double radialVelMps) {
  bool inRange = (distM >= kMinDistM && distM <= kMaxDistM);
  double rawVel = EvalPoly3(kExitVelCoeffs, distM, radialVelMps);
  double rawAng = EvalPoly3(kHoodAngCoeffs, distM, radialVelMps);
  double rawTof = EvalPoly3(kTofCoeffs, distM, radialVelMps);

  bool withinLimits = inRange &&
      (rawVel >= kMinExitVelMps && rawVel <= kMaxExitVelMps) &&
      (rawAng >= kMinHoodDeg && rawAng <= kMaxHoodDeg);

  return {
    std::clamp(rawVel, kMinExitVelMps, kMaxExitVelMps),
    std::clamp(rawAng, kMinHoodDeg, kMaxHoodDeg),
    std::max(0.05, rawTof),
    withinLimits
  };
}